/**
 * TeleVoIPs Virtual Switchboard - the federated entry point the Horizon host loads.
 *
 * Headless orchestrator (renders nothing itself). In one effect it:
 *   - registers TWO full-page routes under /apps (paths set at build time):
 *     the Virtual Switchboard (`switchboard` for the original install) and
 *     Call Flow (`call-flow`), and
 *   - installs the relayed host streams as "live signals" for the pages.
 *
 * /apps has no section floor, so the console is reachable by every scope that
 * runs a switchboard. `requiredScopes` is deliberately unset: the page gates
 * its own modes by scope (model/capabilities.ts, the same tiers as the Engage
 * switchboard) and NetSapiens enforces every read and write with the signed-in
 * user's own permissions, so an agent sees the Real-Time board and their own
 * calls while supervisors also get Operate, Analyze and the Wallboard.
 */
import type { HorizonContext } from '@netsapiens/horizon-sdk';
import { useEffect, useMemo, useRef } from 'react';
import {
  HorizonContextProvider,
  useRemoteApp,
} from '@netsapiens/horizon-sdk';

import SwitchboardPage from './pages/SwitchboardPage';
// Call Flow loads the first time someone opens it (see CallFlowLazy).
import CallFlowPage from './pages/CallFlowLazy';
import { installLiveSignals } from './services/liveSignals';

// Injected at build time by webpack DefinePlugin (see webpack.config.js). The
// SDK derives the kebab app id (__APP_ID__) from the container name; the route
// id, path and label are set per install so two copies can share a platform.
declare const __MF_NAME__: string;
declare const __APP_ID__: string;
declare const __APP_ROUTE__: string;
declare const __APP_LABEL__: string;
declare const __CALLFLOW_ROUTE__: string;

const CALLFLOW_ROUTE_ID = `${__APP_ID__}-call-flow`;

/**
 * Props the host passes to a registered route component. We don't use the demo's
 * test-id harness, so this is just a pass-through bag the page spreads onto its
 * root element.
 */
export type ZoneMarkerProps = Record<string, unknown>;

export default function App(horizonContext: HorizonContext) {
  const { sdk } = useRemoteApp(horizonContext, __MF_NAME__);

  // The host rebuilds `horizonContext` (including `ui`) on every color-mode
  // change. Keep the wrapper identity stable but always read the LATEST context,
  // so the page's `ui` follows the mode the user is actually looking at.
  const contextRef = useRef(horizonContext);
  contextRef.current = horizonContext;

  const SwitchboardWithContext = useMemo(
    () =>
      function SwitchboardWithContext(props: ZoneMarkerProps) {
        return (
          <HorizonContextProvider context={contextRef.current}>
            <SwitchboardPage {...props} />
          </HorizonContextProvider>
        );
      },
    [],
  );
  const CallFlowWithContext = useMemo(
    () =>
      function CallFlowWithContext(props: ZoneMarkerProps) {
        return (
          <HorizonContextProvider context={contextRef.current}>
            <CallFlowPage {...props} />
          </HorizonContextProvider>
        );
      },
    [],
  );

  useEffect(() => {
    sdk
      .registerRoute({
        id: __APP_ID__,
        parentPath: '/apps',
        path: __APP_ROUTE__,
        label: __APP_LABEL__,
        icon: 'mdi:phone-in-talk',
        component: SwitchboardWithContext,
      })
      .catch((error) =>
        console.error('[switchboard] Failed to register route:', error),
      );
    sdk
      .registerRoute({
        id: CALLFLOW_ROUTE_ID,
        parentPath: '/apps',
        path: __CALLFLOW_ROUTE__,
        label: 'Call Flow',
        icon: 'mdi:sitemap',
        component: CallFlowWithContext,
      })
      .catch((error) =>
        console.error('[switchboard] Failed to register the Call Flow route:', error),
      );

    // Subscribe to whatever relayed streams the app is granted; each event
    // nudges the page's pollers. Falls back to pure polling if none are granted.
    const teardownSignals = installLiveSignals(sdk, horizonContext.eventBus);

    return () => {
      sdk.unregisterRoute(__APP_ID__);
      sdk.unregisterRoute(CALLFLOW_ROUTE_ID);
      teardownSignals();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [sdk]);

  return null;
}
