/**
 * The Call Flow page, loaded the first time someone opens it. It carries the
 * crawler and the layout engine, which the switchboard never needs, so they
 * sit in their own chunks; webpack fetches those the same way it fetches the
 * app's other chunks, integrity-checked.
 */
import { Suspense, lazy } from 'react';

import type { ZoneMarkerProps } from '../App';

const CallFlowPage = lazy(() => import(/* webpackChunkName: "call-flow" */ './CallFlowPage'));

export default function CallFlowLazy(props: ZoneMarkerProps) {
  return (
    <Suspense fallback={<PageLoading />}>
      <CallFlowPage {...props} />
    </Suspense>
  );
}

/** Shown while the chunk downloads (usually a blink). */
function PageLoading() {
  return (
    <div role="status" style={{ padding: 24, font: '14px Arial, Helvetica, sans-serif', opacity: 0.7 }}>
      Loading Call Flow...
    </div>
  );
}
