/**
 * Clicks that talk to the switch run through `useActions().run`, which tracks
 * the in-flight key (so a button can show busy and not double-fire) and posts
 * the outcome to a small toast stack the shell renders. The host kit has no
 * snackbar, so the stack is drawn from its Alert.
 */
import type * as React from 'react';
import { createContext, useCallback, useContext, useMemo, useRef, useState } from 'react';

import { describeError } from '../model/errors';

export interface ActionResult {
  id: number;
  status: 'pending' | 'ok' | 'error' | 'info';
  text: string;
}

interface RunOptions {
  /** Shown on success. */
  success?: string;
  /** First half of the failure toast; the reason is appended. */
  failure?: string;
  /** Shown while running (defaults to nothing, the button shows busy). */
  pending?: string;
}

interface ActionsApi {
  run: (key: string, fn: () => Promise<unknown>, opts?: RunOptions) => Promise<boolean>;
  isPending: (key: string) => boolean;
  notify: (status: ActionResult['status'], text: string) => void;
  results: ActionResult[];
  dismiss: (id: number) => void;
}

const Ctx = createContext<ActionsApi | null>(null);

const TTL: Record<ActionResult['status'], number> = { pending: 15000, ok: 5000, info: 6000, error: 9000 };

export function ActionsProvider({ children }: { children: React.ReactNode }) {
  const [results, setResults] = useState<ActionResult[]>([]);
  const [pending, setPending] = useState<Record<string, true>>({});
  const nextId = useRef(1);

  const dismiss = useCallback((id: number) => setResults((rs) => rs.filter((r) => r.id !== id)), []);

  const post = useCallback(
    (status: ActionResult['status'], text: string, replaceId?: number) => {
      const id = replaceId ?? nextId.current++;
      setResults((rs) => {
        const without = rs.filter((r) => r.id !== id);
        return [{ id, status, text }, ...without].slice(0, 5);
      });
      window.setTimeout(() => {
        setResults((rs) => rs.filter((r) => !(r.id === id && r.status === status)));
      }, TTL[status]);
      return id;
    },
    [],
  );

  const notify = useCallback((status: ActionResult['status'], text: string) => void post(status, text), [post]);

  const run = useCallback(
    async (key: string, fn: () => Promise<unknown>, opts: RunOptions = {}) => {
      setPending((p) => ({ ...p, [key]: true }));
      const tid = opts.pending ? post('pending', opts.pending) : undefined;
      try {
        await fn();
        if (opts.success) post('ok', opts.success, tid);
        else if (tid != null) dismiss(tid);
        return true;
      } catch (err) {
        const head = opts.failure ?? 'That did not work.';
        post('error', `${head} ${describeError(err)}`, tid);
        return false;
      } finally {
        setPending((p) => {
          const next = { ...p };
          delete next[key];
          return next;
        });
      }
    },
    [dismiss, post],
  );

  const isPending = useCallback((key: string) => !!pending[key], [pending]);

  const value = useMemo(() => ({ run, isPending, notify, results, dismiss }), [dismiss, isPending, notify, results, run]);
  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

export function useActions(): ActionsApi {
  const v = useContext(Ctx);
  if (!v) throw new Error('useActions must be used inside ActionsProvider');
  return v;
}
