/**
 * Wallboard - the queue board read from across a room (the Engage
 * WallboardOverlay), rendered in the page body in the host theme.
 *
 *   header    title, scope, page n of N, live clock, Privacy, settings
 *   summary   totals over EVERY wallboard queue, not just the page showing
 *   tiles     a grid that fills the remaining height and never scrolls; more
 *             queues than read legibly are paged, optionally rotating
 *
 * Queues are the Real-Time board's: parks excluded, narrowed by its Site and
 * Department filters (search is not applied: a wall display is not a search).
 * Agents come from each queue's roster; the poller refreshes rosters one
 * queue at a time, so a tile shows the queue record's own agent counts until
 * its roster arrives.
 *
 * Not ported, on purpose: desktop notifications, the cross-tab alert channel
 * and the pop-out window. None of them is available to (or portable into) a
 * Horizon app; the in-page banner and the chime stand in for the first.
 */
import type * as React from 'react';
import { memo, useCallback, useEffect, useId, useMemo, useRef, useState } from 'react';

import type { Contact, QueueMember, QueueView } from '../../types';
import { useSwitchboard } from '../../data/SwitchboardData';
import { useNow } from '../../data/clock';
import { isString, usePersistentState } from '../../data/persist';
import { AGENT_STATE, isRoutable, resolveAgentState } from '../../model/agents';
import { callerWaitSeconds } from '../../model/calls';
import { ALL, matchesFilter } from '../../model/directory';
import { formatMinSec, plural } from '../../model/format';
import { baseExtension } from '../../model/raw';
import { BAND_TONE, longestWaitSeconds, waitBand, waitingCount } from '../../model/queues';
import { useKit } from '../../ui/kit';
import { ActionIcon, Dot, tint, toneColor, toneText } from '../../ui/bits';
import type { Tone } from '../../ui/bits';
import {
  DEFAULT_WALLBOARD_SETTINGS,
  MIN_CRITICAL_WAIT_SEC,
  MIN_LONG_WAIT_SEC,
  MIN_ROTATE_SEC,
  describeAlert,
  detectQueueAlerts,
  mostUrgent,
  normalizeSettings,
  paginate,
  pruneAnnounced,
  thresholdsOf,
  tilesPerPage,
  wallboardDensity,
  wallboardGrid,
  wallboardTypeScale,
} from './wallboardModel';
import type { AlertCandidate, QueueAlert, Thresholds, WallboardSettings, WallboardTypeScale } from './wallboardModel';

/** How long the alert banner stays up. */
const BANNER_MS = 20_000;

/** A border (and optional wash) that pulses: a pseudo-element, so the numbers themselves never fade. */
function pulse(tone: Tone, wash: number) {
  return {
    '&::after': {
      content: '""',
      position: 'absolute',
      inset: 0,
      borderRadius: 'inherit',
      pointerEvents: 'none',
      border: '2px solid',
      borderColor: toneColor(tone),
      bgcolor: tint(tone, wash),
      animation: 'tvsbWallPulse 1.4s ease-in-out infinite',
    },
    '@keyframes tvsbWallPulse': { '0%, 100%': { opacity: 1 }, '50%': { opacity: 0.2 } },
  };
}

/** Handset DND by extension (a device-suffixed agent resolves to its person). */
function dndLookup(dnd: ReadonlyMap<string, boolean>, user: string): boolean {
  return dnd.get(user) ?? dnd.get(baseExtension(user)) ?? false;
}

/**
 * Routable over total. The roster when it has loaded (the same verdict the
 * agent dots paint, so a DND handset is not counted as available), otherwise
 * the queue record's own counters.
 */
function agentCounts(q: QueueView, dnd: ReadonlyMap<string, boolean>): { routable: number; total: number } {
  if (q.roster) {
    return { routable: q.roster.filter((m) => isRoutable(m, dndLookup(dnd, m.user))).length, total: q.roster.length };
  }
  return { routable: q.agentsAvailable, total: q.agentsTotal };
}

// ---------------------------------------------------------------------------
// The chime
// ---------------------------------------------------------------------------

type WithWebkit = typeof globalThis & { webkitAudioContext?: typeof AudioContext };

/**
 * A two-note chime synthesized with Web Audio: rising (660 then 880 Hz) for a
 * long wait, falling (880 then 660 Hz) for a critical one, so the two are
 * told apart without looking up. No asset to fetch at the moment it matters.
 * The AudioContext is created on first use (the switch that turns the chime
 * on counts, which also satisfies the browser's gesture rule) and reused.
 */
function useChime() {
  const ctxRef = useRef<AudioContext | null>(null);

  const ensure = useCallback((): AudioContext | null => {
    if (ctxRef.current) return ctxRef.current;
    try {
      const Ctor = window.AudioContext ?? (window as WithWebkit).webkitAudioContext;
      if (!Ctor) return null;
      ctxRef.current = new Ctor();
    } catch {
      return null; // No audio device, or the browser refused a context. Not fatal.
    }
    return ctxRef.current;
  }, []);

  const prime = useCallback(() => {
    const ctx = ensure();
    if (ctx && ctx.state === 'suspended') void ctx.resume().catch(() => undefined);
  }, [ensure]);

  const play = useCallback(
    (critical: boolean) => {
      const ctx = ensure();
      if (!ctx) return;
      try {
        if (ctx.state === 'suspended') void ctx.resume().catch(() => undefined);
        const start = ctx.currentTime + 0.02;
        (critical ? [880, 660] : [660, 880]).forEach((freq, i) => {
          const at = start + i * 0.16;
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();
          osc.type = 'sine';
          osc.frequency.value = freq;
          // Ramped, never a bare start/stop: a square edge on a sine is an audible click.
          gain.gain.setValueAtTime(0.0001, at);
          gain.gain.exponentialRampToValueAtTime(0.22, at + 0.02);
          gain.gain.exponentialRampToValueAtTime(0.0001, at + 0.15);
          osc.connect(gain);
          gain.connect(ctx.destination);
          osc.start(at);
          osc.stop(at + 0.16);
        });
      } catch {
        /* a chime that cannot play must never break the board */
      }
    },
    [ensure],
  );

  useEffect(
    () => () => {
      const ctx = ctxRef.current;
      ctxRef.current = null;
      if (ctx) void ctx.close().catch(() => undefined);
    },
    [],
  );

  return { play, prime };
}

// ---------------------------------------------------------------------------
// The view
// ---------------------------------------------------------------------------

export function WallboardView() {
  const { Box, Stack, Typography, Button, Icon } = useKit();
  const sb = useSwitchboard();

  const [site] = usePersistentState<string>('rt.site', ALL, isString);
  const [dept] = usePersistentState<string>('rt.dept', ALL, isString);
  const [stored, setStored] = usePersistentState<unknown>('wallboard.settings', DEFAULT_WALLBOARD_SETTINGS);
  const settings = useMemo(() => normalizeSettings(stored), [stored]);
  const update = useCallback(
    <K extends keyof WallboardSettings>(key: K, value: WallboardSettings[K]) =>
      setStored((prev: unknown) => ({ ...normalizeSettings(prev), [key]: value })),
    [setStored],
  );
  const thresholds = useMemo(
    () => thresholdsOf(settings.longWaitSec, settings.criticalWaitSec),
    [settings.criticalWaitSec, settings.longWaitSec],
  );
  const chime = useChime();

  const queues = useMemo(
    () => sb.queues.filter((q) => matchesFilter(q.site, site) && matchesFilter(q.department, dept)),
    [dept, sb.queues, site],
  );
  // A wallboard showing three of twenty queues must say so, or it reads as a switch that lost seventeen.
  const scope = [site, dept].filter((v) => v && v !== ALL).join(' · ');
  const dnd = useMemo(() => new Map(sb.contacts.map((c) => [c.user, c.dnd] as const)), [sb.contacts]);

  // The grid box, measured, because the grid FILLS it rather than flowing down it.
  const boxId = useId();
  const [boxEl, setBoxEl] = useState<HTMLElement | null>(null);
  const [area, setArea] = useState({ width: 0, height: 0 });
  useEffect(() => {
    const el = boxEl ?? document.getElementById(boxId);
    if (!el || typeof ResizeObserver === 'undefined') return undefined;
    const measure = (width: number, height: number) =>
      setArea((prev) =>
        Math.abs(prev.width - width) < 1 && Math.abs(prev.height - height) < 1 ? prev : { width, height },
      );
    const ro = new ResizeObserver((entries) => {
      const rect = entries[0]?.contentRect;
      if (rect) measure(rect.width, rect.height);
    });
    ro.observe(el);
    const rect = el.getBoundingClientRect();
    measure(rect.width, rect.height);
    return () => ro.disconnect();
  }, [boxEl, boxId]);

  const measured = area.width > 0 && area.height > 0;
  const perPage = useMemo(
    () => (measured ? tilesPerPage(area.width, area.height) : queues.length || 1),
    [area.height, area.width, measured, queues.length],
  );
  const pages = useMemo(() => paginate(queues, perPage), [perPage, queues]);
  const [page, setPage] = useState(0);
  // Clamped rather than reset: a queue leaving while page four shows must not jump back to page one.
  const safePage = Math.min(page, pages.length - 1);
  const pageQueues = pages[safePage] ?? [];
  const grid = useMemo(
    () => wallboardGrid(pageQueues.length, measured ? area.width / area.height : 16 / 9),
    [area.height, area.width, measured, pageQueues.length],
  );
  const scale = useMemo(
    () => wallboardTypeScale(wallboardDensity(measured ? area.height / grid.rows : 0)),
    [area.height, grid.rows, measured],
  );

  const pageCount = pages.length;
  const step = useCallback(
    (by: number) => setPage((p) => (((Math.min(p, pageCount - 1) + by) % pageCount) + pageCount) % pageCount),
    [pageCount],
  );
  useEffect(() => {
    if (!settings.autoRotate || pageCount <= 1) return undefined;
    const id = window.setInterval(() => step(1), Math.max(MIN_ROTATE_SEC, settings.autoRotateIntervalSec) * 1000);
    return () => window.clearInterval(id);
  }, [pageCount, settings.autoRotate, settings.autoRotateIntervalSec, step]);

  const [settingsOpen, setSettingsOpen] = useState(false);
  const privacy = settings.privacyMode;

  // Both fill the measured box absolutely, so they take its real size whether or
  // not every ancestor's height resolves as definite inside the host page.
  let tiles: React.ReactNode;
  if (!pageQueues.length) {
    tiles = (
      <Stack alignItems="center" justifyContent="center" sx={{ position: 'absolute', inset: 0 }}>
        <Typography variant="body1" color="text.secondary">
          {sb.loading && !sb.queues.length
            ? 'Loading queues...'
            : scope
              ? `No queues to display for ${scope}.`
              : 'No queues to display.'}
        </Typography>
      </Stack>
    );
  } else {
    tiles = (
      <Box
        sx={{
          position: 'absolute',
          inset: 0,
          display: 'grid',
          gap: 2,
          gridTemplateColumns: `repeat(${grid.columns}, minmax(0, 1fr))`,
          gridTemplateRows: `repeat(${grid.rows}, minmax(0, 1fr))`,
        }}
      >
        {pageQueues.map((q) => (
          <WallboardTile
            key={q.ext}
            queue={q}
            scale={scale}
            thresholds={thresholds}
            privacy={privacy}
            dnd={dnd}
            contactsByUser={sb.contactsByUser}
          />
        ))}
      </Box>
    );
  }

  return (
    <Box
      sx={{
        display: 'flex',
        flexDirection: 'column',
        gap: 1.5,
        height: '100%',
        minHeight: 'calc(100vh - 260px)',
        pb: 1,
      }}
    >
      {/* Header */}
      <Stack direction="row" alignItems="center" flexWrap="wrap" sx={{ gap: 1.5, flexShrink: 0 }}>
        <Stack direction="row" alignItems="center" sx={{ gap: 1.5, minWidth: 0, flex: 1 }}>
          <Typography variant="h6" component="h2" sx={{ fontWeight: 800, flexShrink: 0 }}>
            Wallboard
          </Typography>
          {scope ? (
            <Typography variant="body2" color="text.secondary" noWrap title={`Showing ${scope}`} sx={{ minWidth: 0 }}>
              Showing {scope}
            </Typography>
          ) : null}
          {pageCount > 1 ? (
            <Stack direction="row" alignItems="center" sx={{ flexShrink: 0 }}>
              <ActionIcon icon="lucide:chevron-left" label="Previous page" onClick={() => step(-1)} />
              <Typography variant="body2" color="text.secondary" sx={{ fontVariantNumeric: 'tabular-nums', px: 0.5 }}>
                Page {safePage + 1} of {pageCount}
              </Typography>
              <ActionIcon icon="lucide:chevron-right" label="Next page" onClick={() => step(1)} />
            </Stack>
          ) : null}
        </Stack>
        <WallboardClock />
        {/*
          Privacy sits in the header, not only in settings: it is what an
          operator flips because somebody just walked in. Labeled with the
          CURRENT state, which is what a glance at a wall display needs.
        */}
        <Button
          size="small"
          variant={privacy ? 'contained' : 'outlined'}
          color={privacy ? 'primary' : 'inherit'}
          aria-pressed={privacy}
          onClick={() => update('privacyMode', !privacy)}
          startIcon={<Icon name={privacy ? 'lucide:eye-off' : 'lucide:eye'} size={16} />}
          sx={{ textTransform: 'none', fontWeight: 600, whiteSpace: 'nowrap' }}
        >
          {privacy ? 'Privacy on' : 'Privacy off'}
        </Button>
        <ActionIcon icon="lucide:settings" label="Wallboard settings" onClick={() => setSettingsOpen(true)} />
      </Stack>

      <WallboardSummary queues={queues} thresholds={thresholds} dnd={dnd} />

      {/* The grid box. The alert banner floats over it so a crossing never re-lays out the tiles. */}
      <Box ref={setBoxEl} id={boxId} sx={{ flex: 1, minHeight: 0, position: 'relative' }}>
        <WallboardAlerts
          queues={queues}
          thresholds={thresholds}
          privacy={privacy}
          sound={settings.alertSound}
          playChime={chime.play}
        />
        {tiles}
      </Box>

      <WallboardSettingsPanel
        open={settingsOpen}
        onClose={() => setSettingsOpen(false)}
        settings={settings}
        update={update}
        onChimeOn={chime.prime}
        queueCount={queues.length}
        pageCount={pageCount}
      />
    </Box>
  );
}

// ---------------------------------------------------------------------------
// Header clock and summary bar
// ---------------------------------------------------------------------------

function WallboardClock() {
  const now = useNow();
  const { Typography } = useKit();
  return (
    <Typography
      variant="h6"
      component="div"
      aria-label="Current time"
      sx={{ fontVariantNumeric: 'tabular-nums', fontWeight: 600, color: 'text.secondary', whiteSpace: 'nowrap' }}
    >
      {new Date(now).toLocaleTimeString()}
    </Typography>
  );
}

function WallboardSummary({
  queues,
  thresholds,
  dnd,
}: {
  queues: QueueView[];
  thresholds: Thresholds;
  dnd: ReadonlyMap<string, boolean>;
}) {
  const now = useNow();
  const { Paper, Stack, Typography } = useKit();
  let waiting = 0;
  let active = 0;
  let longest = 0;
  let available = 0;
  for (const q of queues) {
    waiting += waitingCount(q);
    active += q.active.length;
    longest = Math.max(longest, longestWaitSeconds(q, now));
    available += agentCounts(q, dnd).routable;
  }
  const band = waitBand(longest, thresholds);
  const critical = band === 'critical';
  const items: Array<{ label: string; value: string; tone: Tone }> = [
    { label: 'Waiting', value: String(waiting), tone: waiting > 0 ? (critical ? 'error' : 'warning') : 'success' },
    { label: 'Available', value: String(available), tone: available > 0 ? 'success' : 'error' },
    { label: 'Longest Wait', value: formatMinSec(longest), tone: band === 'ok' ? 'neutral' : BAND_TONE[band] },
    { label: 'Active', value: String(active), tone: 'info' },
  ];
  return (
    <Paper
      variant="outlined"
      role="group"
      aria-label="Wallboard totals"
      sx={{ p: 1.5, flexShrink: 0, position: 'relative', overflow: 'hidden', ...(critical ? pulse('error', 0.06) : {}) }}
    >
      <Stack direction="row" justifyContent="center" flexWrap="wrap" sx={{ columnGap: 6, rowGap: 1 }}>
        {items.map((i) => (
          <Stack key={i.label} alignItems="center" sx={{ minWidth: 80 }}>
            <Typography
              component="div"
              sx={{
                fontSize: 28,
                fontWeight: 800,
                lineHeight: 1.15,
                fontVariantNumeric: 'tabular-nums',
                color: i.tone === 'neutral' ? 'text.secondary' : toneText(i.tone),
              }}
            >
              {i.value}
            </Typography>
            <Typography component="div" sx={{ fontSize: 12, fontWeight: 600, color: 'text.secondary' }}>
              {i.label}
            </Typography>
          </Stack>
        ))}
      </Stack>
    </Paper>
  );
}

// ---------------------------------------------------------------------------
// A tile
// ---------------------------------------------------------------------------

function WallboardTile({
  queue,
  scale,
  thresholds,
  privacy,
  dnd,
  contactsByUser,
}: {
  queue: QueueView;
  scale: WallboardTypeScale;
  thresholds: Thresholds;
  privacy: boolean;
  dnd: ReadonlyMap<string, boolean>;
  contactsByUser: Map<string, Contact>;
}) {
  const now = useNow();
  const { Box, Paper, Stack, Typography } = useKit();
  const waiting = waitingCount(queue);
  const longest = longestWaitSeconds(queue, now);
  const band = waitBand(longest, thresholds);
  const { routable, total } = agentCounts(queue, dnd);

  const border: Tone =
    total === 0 ? 'neutral' : waiting === 0 ? 'success' : band === 'critical' ? 'error' : band === 'long' ? 'warning' : 'info';
  const waitingTone: Tone = waiting > 0 ? (band === 'critical' ? 'error' : 'warning') : 'success';
  const metrics: Array<{ label: string; value: string; tone: Tone }> = [
    { label: 'Waiting', value: String(waiting), tone: waitingTone },
    { label: 'Agents', value: `${routable}/${total}`, tone: routable > 0 ? 'success' : 'error' },
    { label: 'Max Wait', value: formatMinSec(longest), tone: band === 'ok' ? 'neutral' : BAND_TONE[band] },
  ];

  const shown = queue.waiting.slice(0, scale.callerRows);
  const more = Math.max(0, waiting - shown.length);

  return (
    <Paper
      variant="outlined"
      aria-label={`${queue.name} queue`}
      sx={{
        p: scale.padding,
        minHeight: 0,
        minWidth: 0,
        overflow: 'hidden',
        position: 'relative',
        display: 'flex',
        flexDirection: 'column',
        border: '2px solid',
        borderColor: tint(border, border === 'neutral' ? 0.35 : 0.55),
        ...(border === 'error' ? pulse('error', 0) : {}),
      }}
    >
      <Stack direction="row" alignItems="baseline" justifyContent="space-between" spacing={1} sx={{ flexShrink: 0, mb: 1, minWidth: 0 }}>
        <Typography noWrap title={queue.name} sx={{ fontSize: scale.title, fontWeight: 700, minWidth: 0 }}>
          {queue.name}
        </Typography>
        <Typography sx={{ fontSize: scale.metricLabel, color: 'text.secondary', fontVariantNumeric: 'tabular-nums', flexShrink: 0 }}>
          {queue.ext}
        </Typography>
      </Stack>

      {/* Auto margins center the three numbers in whatever the caller list leaves. */}
      <Box sx={{ display: 'grid', gridTemplateColumns: 'repeat(3, minmax(0, 1fr))', gap: 1, flexShrink: 0, my: 'auto' }}>
        {metrics.map((m) => (
          <Box key={m.label} sx={{ textAlign: 'center', minWidth: 0 }}>
            <Typography
              component="div"
              sx={{
                fontSize: scale.metric,
                fontWeight: 800,
                lineHeight: 1,
                fontVariantNumeric: 'tabular-nums',
                color: m.tone === 'neutral' ? 'text.secondary' : toneText(m.tone),
              }}
            >
              {m.value}
            </Typography>
            <Typography component="div" sx={{ fontSize: scale.metricLabel, color: 'text.secondary', mt: 0.5 }}>
              {m.label}
            </Typography>
          </Box>
        ))}
      </Box>

      {scale.callerRows > 0 ? (
        <Stack spacing={0.5} sx={{ mt: 1.5, minHeight: 0, flexShrink: 1, overflow: 'hidden' }}>
          {shown.map((c, i) => {
            const label = privacy || c.placeholder ? `Caller ${i + 1}` : c.callerName || c.callerNumber || 'Unknown';
            const wait = c.placeholder ? null : callerWaitSeconds(c, now);
            const tone = wait == null ? 'neutral' : BAND_TONE[waitBand(wait, thresholds)];
            return (
              <Stack key={c.key} direction="row" justifyContent="space-between" spacing={1} sx={{ minWidth: 0 }}>
                <Typography noWrap sx={{ fontSize: scale.caller, color: 'text.secondary', minWidth: 0 }}>
                  {label}
                </Typography>
                {wait != null ? (
                  <Typography sx={{ fontSize: scale.caller, fontWeight: 700, fontVariantNumeric: 'tabular-nums', color: toneText(tone), flexShrink: 0 }}>
                    {formatMinSec(wait)}
                  </Typography>
                ) : null}
              </Stack>
            );
          })}
          {more > 0 ? (
            <Typography sx={{ fontSize: scale.caller, color: 'text.secondary' }}>+{more} more</Typography>
          ) : null}
          {waiting === 0 ? (
            <Typography sx={{ fontSize: scale.caller, color: 'text.secondary' }}>No calls waiting</Typography>
          ) : null}
        </Stack>
      ) : null}

      {queue.roster ? (
        <AgentDots roster={queue.roster} privacy={privacy} contactsByUser={contactsByUser} />
      ) : null}
    </Paper>
  );
}

/**
 * One dot per roster member, on the same agent-state vocabulary as every other
 * mode. Dots only: the board is read from across a room, and the tooltip names
 * the person for anyone close enough to hover. Memoized so the per-second tick
 * of the tile does not redraw a tooltip per agent.
 */
const AgentDots = memo(function AgentDots({
  roster,
  privacy,
  contactsByUser,
}: {
  roster: QueueMember[];
  privacy: boolean;
  contactsByUser: Map<string, Contact>;
}) {
  const { Stack } = useKit();
  if (!roster.length) return null;
  return (
    <Stack direction="row" flexWrap="wrap" sx={{ gap: 0.5, mt: 1, flexShrink: 0 }} aria-label="Agents in this queue">
      {roster.map((m) => {
        const contact = contactsByUser.get(m.user) ?? contactsByUser.get(baseExtension(m.user));
        const state = resolveAgentState([], m.status, {
          dnd: contact?.dnd ?? false,
          loggedOut: m.loggedOut,
          offline: false,
        });
        const info = AGENT_STATE[state];
        return (
          <Dot
            key={`${m.queue}:${m.user}`}
            tone={info.tone}
            size={10}
            title={privacy ? m.user : `${m.name} (${m.user}): ${info.label}`}
          />
        );
      })}
    </Stack>
  );
});

// ---------------------------------------------------------------------------
// Alerts: the chime and the banner
// ---------------------------------------------------------------------------

/**
 * Watches every waiting caller on the wallboard (every page, not only the one
 * showing: rotation must not silence four queues out of five) and raises each
 * crossing once per caller per band. Crossings are recorded whether or not the
 * chime is on, so switching it on mid-afternoon starts with what happens NEXT
 * rather than replaying everyone already waiting.
 */
function WallboardAlerts({
  queues,
  thresholds,
  privacy,
  sound,
  playChime,
}: {
  queues: QueueView[];
  thresholds: Thresholds;
  privacy: boolean;
  sound: boolean;
  playChime: (critical: boolean) => void;
}) {
  const now = useNow();
  const { Box, Alert } = useKit();
  const announced = useRef<Set<string>>(new Set());
  const [banner, setBanner] = useState<QueueAlert | null>(null);
  const soundRef = useRef(sound);
  soundRef.current = sound;

  // Measured against one instant, the clock tick, so a caller in an otherwise
  // quiet queue still crosses: nothing else would re-run this.
  const candidates = useMemo<AlertCandidate[]>(() => {
    const out: AlertCandidate[] = [];
    for (const q of queues) {
      for (const c of q.waiting) {
        if (c.placeholder) continue;
        out.push({
          id: c.controlIds[0] || c.key,
          queueExt: q.ext,
          queueName: q.name,
          callerLabel: c.callerName || c.callerNumber || 'A caller',
          waitSeconds: callerWaitSeconds(c, now),
        });
      }
    }
    return out;
  }, [now, queues]);

  useEffect(() => {
    // Forget callers who were answered or hung up first, so a reissued id can alert again.
    announced.current = pruneAnnounced(announced.current, new Set(candidates.map((c) => c.id)));
    const { alerts, alsoSeen } = detectQueueAlerts(candidates, thresholds, announced.current);
    for (const key of alsoSeen) announced.current.add(key);
    if (!alerts.length) return;
    for (const a of alerts) announced.current.add(a.key);
    const top = mostUrgent(alerts);
    if (!top) return;
    setBanner(top);
    // One chime per batch, at the batch's highest urgency, rather than one per caller at once.
    if (soundRef.current) playChime(top.band === 'critical');
  }, [candidates, playChime, thresholds]);

  useEffect(() => {
    if (!banner) return undefined;
    const id = window.setTimeout(() => setBanner(null), BANNER_MS);
    return () => window.clearTimeout(id);
  }, [banner]);

  if (!banner) return null;
  return (
    <Box
      aria-live="polite"
      sx={{
        position: 'absolute',
        top: 8,
        left: '50%',
        transform: 'translateX(-50%)',
        zIndex: 2,
        width: 'min(720px, calc(100% - 16px))',
      }}
    >
      <Alert severity={banner.band === 'critical' ? 'error' : 'warning'} onClose={() => setBanner(null)}>
        {describeAlert(banner, privacy)}
      </Alert>
    </Box>
  );
}

