function WallboardSettingsPanel({
  open,
  onClose,
  settings,
  update,
  onChimeOn,
  queueCount,
  pageCount,
}: {
  open: boolean;
  onClose: () => void;
  settings: WallboardSettings;
  update: <K extends keyof WallboardSettings>(key: K, value: WallboardSettings[K]) => void;
  onChimeOn: () => void;
  queueCount: number;
  pageCount: number;
}) {
  const { SidePanel, Stack, Switch, Typography, Icon } = useKit();
  return (
    <SidePanel
      open={open}
      onClose={onClose}
      title="Wallboard settings"
      subtitle="Saved in this browser"
      icon={<Icon name="lucide:settings" size={20} />}
      width="sm"
    >
      <Stack spacing={3}>
        <SettingsSection title="Privacy">
          <Switch
            label="Privacy Mode"
            checked={settings.privacyMode}
            onChange={(_e: unknown, checked: boolean) => update('privacyMode', checked)}
          />
          <Typography variant="caption" color="text.secondary">
            Hides caller names and numbers, and agent names, on the tiles and in alerts.
          </Typography>
        </SettingsSection>

        <SettingsSection title="Wait thresholds">
          <NumberSetting
            label="Long wait (seconds)"
            value={settings.longWaitSec}
            min={MIN_LONG_WAIT_SEC}
            helper={`Waits this long turn amber. At least ${MIN_LONG_WAIT_SEC} seconds.`}
            onCommit={(v) => update('longWaitSec', v)}
          />
          <NumberSetting
            label="Critical wait (seconds)"
            value={settings.criticalWaitSec}
            min={MIN_CRITICAL_WAIT_SEC}
            helper={`Waits this long turn red and raise an alert. At least ${MIN_CRITICAL_WAIT_SEC} seconds, and never below the long wait.`}
            onCommit={(v) => update('criticalWaitSec', v)}
          />
        </SettingsSection>

        <SettingsSection title="Alerts">
          <Typography variant="caption" color="text.secondary">
            Raised once per caller when they cross a threshold above, on every queue on this wallboard. A banner
            shows the latest one for 20 seconds.
          </Typography>
          <Switch
            label="Play a chime"
            checked={settings.alertSound}
            onChange={(_e: unknown, checked: boolean) => {
              if (checked) onChimeOn();
              update('alertSound', checked);
            }}
          />
        </SettingsSection>

        <SettingsSection title="Display">
          <Switch
            label="Auto-rotate pages"
            checked={settings.autoRotate}
            onChange={(_e: unknown, checked: boolean) => update('autoRotate', checked)}
          />
          <Typography variant="caption" color="text.secondary">
            {pageCount > 1
              ? `${plural(queueCount, 'queue')} across ${pageCount} pages at this size.`
              : 'Every queue fits on one page at this size.'}
          </Typography>
          {settings.autoRotate ? (
            <NumberSetting
              label="Rotate interval (seconds)"
              value={settings.autoRotateIntervalSec}
              min={MIN_ROTATE_SEC}
              helper={`At least ${MIN_ROTATE_SEC} seconds.`}
              onCommit={(v) => update('autoRotateIntervalSec', v)}
            />
          ) : null}
        </SettingsSection>
      </Stack>
    </SidePanel>
  );
}

function SettingsSection({ title, children }: { title: string; children: React.ReactNode }) {
  const { Stack, Typography } = useKit();
  return (
    <Stack spacing={1.25}>
      <Typography variant="overline" sx={{ fontWeight: 700, color: 'text.secondary', lineHeight: 1.5 }}>
        {title}
      </Typography>
      {children}
    </Stack>
  );
}

/**
 * A whole-seconds field that commits on blur or Enter, clamped to its
 * minimum. Clamping on every keystroke would turn the "1" of "12" into the
 * minimum before the "2" arrived.
 */
function NumberSetting({
  label,
  value,
  min,
  helper,
  onCommit,
}: {
  label: string;
  value: number;
  min: number;
  helper: string;
  onCommit: (value: number) => void;
}) {
  const { TextField } = useKit();
  const [draft, setDraft] = useState(String(value));
  useEffect(() => setDraft(String(value)), [value]);
  const commit = () => {
    const n = Math.round(Number(draft));
    if (draft.trim() === '' || !Number.isFinite(n)) {
      setDraft(String(value));
      return;
    }
    const next = Math.max(min, n);
    setDraft(String(next));
    if (next !== value) onCommit(next);
  };
  return (
    <TextField
      size="small"
      type="number"
      label={label}
      value={draft}
      fullWidth
      helperText={helper}
      inputProps={{ min, step: 1, inputMode: 'numeric' }}
      onChange={(e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => setDraft(e.target.value)}
      onBlur={commit}
      onKeyDown={(e: React.KeyboardEvent) => {
        if (e.key === 'Enter') commit();
      }}
    />
  );
}
