/**
 * Every NetSapiens call the switchboard makes, through the host API proxy.
 *
 * Paths are relative to the NetSapiens v2 API root (the proxy prefixes it and
 * injects auth).
 * Only GET / POST / PUT / DELETE are available to apps, so every function here
 * uses one of those. The NetSapiens verbs that are PATCH (answer, hold,
 * unhold, transfer, voicemail move) and every v1 `?object=` read are absent on
 * purpose; `BLOCKED` below documents them for the UI.
 *
 * Paths and bodies mirror the Engage switchboard's SDK calls
 * (packages/netsapiens-sdk/src/resources/*), so these are the same requests
 * Engage already makes against the same switch.
 */
import type { HorizonApiClient } from '@netsapiens/horizon-sdk';

import type {
  CallLeg,
  NsAgent,
  NsAnswerRule,
  NsCallQueue,
  NsCdr,
  NsDomain,
  NsRecord,
  NsUser,
  NsVoicemail,
} from '../types';
import { newCallId, normaliseCalls } from '../model/calls';
import { lower, toFloat } from '../model/raw';

type Api = HorizonApiClient;
const e = encodeURIComponent;

function asArray<T>(v: unknown): T[] {
  if (Array.isArray(v)) return v as T[];
  if (v && typeof v === 'object') {
    const o = v as { data?: unknown; items?: unknown };
    if (Array.isArray(o.data)) return o.data as T[];
    if (Array.isArray(o.items)) return o.items as T[];
  }
  return [];
}

function isNotFound(err: unknown): boolean {
  if (!err || typeof err !== 'object') return false;
  const o = err as { statusCode?: unknown; status?: unknown; message?: unknown };
  return (
    o.statusCode === 404 ||
    o.status === 404 ||
    (typeof o.message === 'string' && /\b404\b|not found|no route found/i.test(o.message))
  );
}

/**
 * Run a call-control request against each candidate call id until one is
 * accepted. A call has an originating and a terminating leg id; which one the
 * switch expects depends on which side the acting user is on, so a 404 on the
 * first moves on to the next instead of failing the click.
 */
async function withCallIds<T>(ids: string[], fn: (id: string) => Promise<T>): Promise<T> {
  const list = ids.filter(Boolean);
  if (!list.length) throw new Error('This call has no id the phone system can act on yet.');
  let lastErr: unknown;
  for (const id of list) {
    try {
      return await fn(id);
    } catch (err) {
      lastErr = err;
      if (!isNotFound(err)) throw err;
    }
  }
  throw lastErr;
}

