export async function readUsers(api: Api, d: string): Promise<NsUser[]> {
  return asArray<NsUser>(await api.get(`/domains/${e(d)}/users`, { limit: 1000 }));
}

export async function readUser(api: Api, d: string, u: string): Promise<NsUser | null> {
  const r = await api.get<NsUser | NsUser[]>(`/domains/${e(d)}/users/${e(u)}`);
  return Array.isArray(r) ? r[0] ?? null : r ?? null;
}

