export async function readAgent(api: Api, d: string, q: string, aid: string): Promise<NsAgent | null> {
  const r = await api.get<NsAgent | NsAgent[]>(`/domains/${e(d)}/callqueues/${e(q)}/agents/${e(aid)}`);
  return Array.isArray(r) ? r[0] ?? null : r ?? null;
}

export async function addAgent(api: Api, d: string, q: string, aid: string): Promise<void> {
  await api.post(`/domains/${e(d)}/callqueues/${e(q)}/agents`, { 'callqueue-agent-id': aid });
}

export async function removeAgent(api: Api, d: string, q: string, aid: string): Promise<void> {
  await api.delete(`/domains/${e(d)}/callqueues/${e(q)}/agents/${e(aid)}`);
}

/**
 * Flip "Taking calls" and read it back. The switch answers 202 to any value,
 * so the read-back is the only confirmation the change landed.
 */
export async function setTakingCalls(api: Api, d: string, q: string, aid: string, on: boolean): Promise<void> {
  const want = on ? 'automatic' : 'manual';
  await api.put(`/domains/${e(d)}/callqueues/${e(q)}/agents/${e(aid)}`, {
    'callqueue-agent-availability-type': want,
  });
  const back = await readAgent(api, d, q, aid);
  const got = lower(back?.['callqueue-agent-availability-type']);
  const ok = on ? got === 'automatic' || got === 'offnet-automatic' : got === 'manual';
  if (!ok) {
    throw new Error(
      `${on ? 'Taking calls' : 'Stop taking calls'} was not applied by the phone system (it still reads ${got || 'nothing'}).`,
    );
  }
}

export async function setCallLimit(api: Api, d: string, q: string, aid: string, limit: number): Promise<void> {
  await api.put(`/domains/${e(d)}/callqueues/${e(q)}/agents/${e(aid)}`, {
    'limits-max-active-calls-total': limit,
  });
  const back = await readAgent(api, d, q, aid);
  const got = toFloat(back?.['limits-max-active-calls-total']);
  if (got !== limit) {
    throw new Error(`Max calls was not applied by the phone system (it still reads ${got || 'nothing'}).`);
  }
}

// ---------------------------------------------------------------------------
// Call control (operator's own calls)
// ---------------------------------------------------------------------------

/**
 * Click-to-call: the operator's phone rings first, then the destination.
 *
 * v46 names the destination `call-term-user` (and requires it); `destination`
 * is what older switches and the Engage SDK send. Both are sent: an unknown
 * key is ignored, a missing required one is a failed call.
 */
export async function originate(api: Api, d: string, u: string, destination: string): Promise<void> {
  await api.post(`/domains/${e(d)}/users/${e(u)}/calls`, {
    synchronous: 'no',
    'call-id': newCallId(),
    'call-term-user': destination,
    destination,
  });
}

export async function hangUp(api: Api, d: string, u: string, ids: string[]): Promise<void> {
  await withCallIds(ids, (id) => api.delete(`/domains/${e(d)}/users/${e(u)}/calls/${e(id)}`));
}

/** Decline a ringing leg so the answer rule moves on (v2 DELETE .../reject). */
export async function decline(api: Api, d: string, u: string, ids: string[]): Promise<void> {
  await withCallIds(ids, (id) => api.delete(`/domains/${e(d)}/users/${e(u)}/calls/${e(id)}/reject`));
}

// ---------------------------------------------------------------------------
// Call control through PUT
//
// NetSapiens documents answer, hold, unhold and transfer as PATCH, which the
// Horizon proxy does not carry. The v46 switch routes PUT to the same
// handlers (verified on the lab: PUT .../voicemails/new/<file>/save moved the
// message exactly as PATCH does, and every call verb below answers PUT with the
// PATCH response, while a verb it does not know answers 405). It is not in the
// published reference, so nothing here trusts the answer: the switch says 202
// Accepted even for a call id it has never heard of. Each verb reads the call
// back and only reports success once the switch shows the change.
// ---------------------------------------------------------------------------

/**
 * One call, as the operator's controls need it. A call has two legs, and the
 * verbs do not act on the same one:
 *   - `own`  the operator's leg: answer, decline and hang up act on it.
 *   - `peer` the other party's leg: park and transfer MOVE it. Moving the
 *            operator's own leg instead parks the operator and cuts the caller
 *            off, which is exactly what 0.3.0 did on an outbound call (it moved
 *            the first id, and on a call the operator placed that is their own
 *            leg). The legacy console always moves "the leg the operator is
 *            not on" for the same reason.
 * `ids` and `sessionId` are only for finding the call again afterwards.
 */
export interface CallRef {
  own: string;
  peer: string;
  ids: string[];
  sessionId: string;
}

export class CallGoneError extends Error {
  constructor(message = 'The call ended before the phone system applied that.') {
    super(message);
    this.name = 'CallGoneError';
  }
}

const sleep = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));

/**
 * Poll `check` until it answers something other than `undefined`, or the time
 * runs out (then `undefined`). A failed read is not an answer.
 */
async function settle<T>(check: () => Promise<T | undefined>, ms: number, every = 800): Promise<T | undefined> {
  const end = Date.now() + ms;
  while (Date.now() < end) {
    await sleep(every);
    try {
      const v = await check();
      if (v !== undefined) return v;
    } catch (err) {
      // A call that is gone will not come back; anything else, try again.
      if (err instanceof CallGoneError) throw err;
    }
  }
  return undefined;
}

/** The operator's own record of the call, if the switch still has it. */
async function findOwnCall(api: Api, d: string, u: string, ref: CallRef): Promise<CallLeg | null> {
  const legs = normaliseCalls(await readUserCalls(api, d, u));
  return (
    legs.find(
      (c) => (ref.sessionId && c.sessionId === ref.sessionId) || c.controlIds.some((id) => ref.ids.includes(id)),
    ) ?? null
  );
}

function isHeldLeg(c: CallLeg): boolean {
  return /held|hold/.test(`${c.origInfo} ${c.termInfo}`);
}

/** Try each id in turn; the next is only tried once the last one visibly did nothing. */
async function actOnCall(
  order: string[],
  send: (id: string) => Promise<unknown>,
  applied: () => Promise<boolean | undefined>,
  wait: number,
  notApplied: string,
): Promise<void> {
  const ids = Array.from(new Set(order.filter(Boolean)));
  if (!ids.length) throw new Error('This call has no id the phone system can act on yet.');
  for (const id of ids) {
    try {
      await send(id);
    } catch (err) {
      if (isNotFound(err)) continue;
      throw err;
    }
    const done = await settle(async () => ((await applied()) ? true : undefined), wait);
    if (done) return;
  }
  throw new Error(notApplied);
}

/** Put the operator's call on hold, or take it off hold. */
export async function setHold(api: Api, d: string, u: string, ref: CallRef, hold: boolean): Promise<void> {
  await actOnCall(
    [ref.own, ref.peer],
    (id) => api.put(`/domains/${e(d)}/users/${e(u)}/calls/${e(id)}/${hold ? 'hold' : 'unhold'}`, {}),
    async () => {
      const c = await findOwnCall(api, d, u, ref);
      if (!c) throw new CallGoneError();
      return isHeldLeg(c) === hold;
    },
    3500,
    hold
      ? 'The phone system accepted the hold, but the call is not on hold. Use your phone to hold it.'
      : 'The phone system accepted the resume, but the call is still on hold. Use your phone to resume it.',
  );
}

/**
 * Blind transfer: the caller goes to `destination` (an extension, a queue's
 * extension or a number) and the operator drops out. Done once the call has
 * left the operator's line.
 */
export async function transferCall(api: Api, d: string, u: string, ref: CallRef, destination: string): Promise<void> {
  // Only ever the caller's leg: moving the operator's own leg would send the
  // operator to the destination and drop the caller.
  if (!ref.peer) throw new Error("The phone system has not reported the other side of this call yet, so it cannot be transferred safely. Try again in a moment.");
  await api.put(`/domains/${e(d)}/users/${e(u)}/calls/${e(ref.peer)}/transfer`, {
    destination,
    'call-term-user': destination,
  });
  const left = await settle(async () => (!(await findOwnCall(api, d, u, ref)) ? true : undefined), 5000);
  if (!left) throw new Error('The phone system accepted the transfer, but the call is still on your line.');
}

/** Calls the switch reports parked in one slot, or null where it has no counter. */
export async function readParkCount(api: Api, d: string, slot: string): Promise<number | null> {
  try {
    const r = await api.get<NsRecord>(`/domains/${e(d)}/parks/${e(slot)}`);
    const n = Number(r?.['parked-calls-total-current']);
    return Number.isFinite(n) ? n : null;
  } catch {
    return null;
  }
}

/**
 * Park = transfer the CALLER's leg to the park slot, which is how the legacy
 * console parks (NetSapiens documents no park operation, and the v2 `/park`
 * route answers "Resource not found" for every call). On v46 the slot's user
 * forwards to `queue_<slot>`, the park orbit.
 *
 * Done only when the slot's own counter (v46 `/parks`) goes up. The call
 * leaving the operator's line is NOT proof: 0.3.0 reported "parked" on exactly
 * that while the caller had been cut off. A switch without the counter falls
 * back to the call leaving the line, and says so.
 */
export async function parkCall(api: Api, d: string, u: string, ref: CallRef, slot: string): Promise<'parked' | 'sent'> {
  if (!ref.peer) {
    throw new Error("The phone system has not reported the caller's side of this call yet, so it cannot be parked safely. Try again in a moment.");
  }
  const before = await readParkCount(api, d, slot);
  await api.put(`/domains/${e(d)}/users/${e(u)}/calls/${e(ref.peer)}/transfer`, {
    destination: slot,
    'call-term-user': slot,
  });
  if (before == null) {
    const left = await settle(async () => (!(await findOwnCall(api, d, u, ref)) ? true : undefined), 5000);
    if (!left) throw new Error('The phone system accepted the park request, but the call is still on your line.');
    return 'sent';
  }
  const counted = await settle(async () => {
    const n = await readParkCount(api, d, slot);
    return n != null && n > before ? n : undefined;
  }, 6000);
  if (counted != null) return 'parked';
  const still = await findOwnCall(api, d, u, ref).catch(() => null);
  throw new Error(
    still
      ? `The phone system accepted the park request, but the call is still on your line (slot ${slot} did not fill).`
      : `The call left your line but never arrived in park ${slot}, so the phone system may have disconnected it.`,
  );
}

/**
 * Retrieve whatever is parked in `slot`: the operator's phone rings, and
 * answering it dials the slot, which is how NetSapiens hands a parked caller
 * back (the same as dialling the slot or pressing its BLF key). v2 `unpark`
 * answers 405 on this switch.
 */
export async function retrieveParked(api: Api, d: string, u: string, slot: string): Promise<void> {
  await originate(api, d, u, slot);
}

/**
 * Answer a ringing call on the operator's device. `device` is the SIP URI the
 * switch is ringing (the leg's term URI); the switch requires one.
 */
export async function answerCall(api: Api, d: string, u: string, ref: CallRef, device: string): Promise<void> {
  await actOnCall(
    [ref.own, ref.peer],
    (id) => api.put(`/domains/${e(d)}/users/${e(u)}/calls/${e(id)}/answer`, { destination: device }),
    async () => {
      const c = await findOwnCall(api, d, u, ref);
      if (!c) throw new CallGoneError('The call stopped ringing before it could be answered.');
      return c.answeredAt != null;
    },
    4000,
    'The phone system accepted the answer, but your phone did not pick up. Answer it on the phone.',
  );
}

