/** Object keyed by dialed number. */
export async function readDnisStats(api: Api, d: string, w: StatsWindow): Promise<Record<string, NsRecord>> {
  const r = await api.get(`/domains/${e(d)}/statistics/dnis`, statsParams(w));
  return r && typeof r === 'object' && !Array.isArray(r) ? (r as Record<string, NsRecord>) : {};
}

