/**
 * Move a voicemail to the Saved folder. Documented as PATCH; the switch routes
 * PUT to the same handler (verified on the lab: the message left New and
 * appeared in Saved). Confirmed by reading the Saved folder back.
 */
export async function saveVoicemail(api: Api, d: string, u: string, folder: VoicemailFolder, id: string): Promise<void> {
  await api.put(`/domains/${e(d)}/users/${e(u)}/voicemails/${e(folder)}/${e(id)}/save`, {});
  const landed = await settle(async () => {
    const saved = await readVoicemails(api, d, u, 'save', 0, 100);
    return saved.some((v) => String(v.filename ?? v.id ?? '') === id) ? true : undefined;
  }, 4000);
  if (!landed) throw new Error('The phone system accepted the move, but the message is not in Saved yet.');
}
